///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_searchCorpList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchCorpList = async function () {
    const sbmOptions = {
        id: "tx_searchCorpList",
        method: "post",
        action: "/listInvstg/comInfoSearchPop.do?method=searchSpecyValuCorp",
        ref: "dma_searchCorpListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil59600.tx_searchCorpList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_searchCorpListByBeginIndex
 * @author Inswave
