        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/comInfoSearchPop.do?method=searchSpecyValuCorp",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil59600.tx_searchCorpListByBeginIndex" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


